using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
namespace Arcoll.WinUI3.Services.BackupCenter;
public static class BackupSafety
{
 public static string HashText(string text)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text))).ToLowerInvariant();
 public static string HashFile(string path){using var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read);return Convert.ToHexString(SHA256.HashData(stream)).ToLowerInvariant();}
 public static async Task<string> HashFileAsync(string path,Func<long,Task>? progress,CancellationToken ct){await using var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read,1048576,true);using var sha=IncrementalHash.CreateHash(HashAlgorithmName.SHA256);var buffer=new byte[1048576];int size;while((size=await stream.ReadAsync(buffer,ct))>0){sha.AppendData(buffer,0,size);if(progress is not null)await progress(size);}return Convert.ToHexString(sha.GetHashAndReset()).ToLowerInvariant();}
 public static bool Inside(string path,string root){var p=Path.GetFullPath(path);var r=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar);return p.Equals(r,StringComparison.OrdinalIgnoreCase)||p.StartsWith(r+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase);}
 public static void NoLinks(string path){var part=Path.GetFullPath(path);while(!string.IsNullOrEmpty(part)){if(File.Exists(part)||Directory.Exists(part))if((File.GetAttributes(part)&FileAttributes.ReparsePoint)!=0)throw new IOException("Junção/link de sistema de arquivos não permitido.");var parent=Path.GetDirectoryName(part);if(parent==part)break;part=parent??"";}}
 public static void DataRoot(string path){var full=Path.GetFullPath(path);if(!full.StartsWith(@"\\")&&full.TrimEnd(Path.DirectorySeparatorChar).Equals(Path.GetPathRoot(full)?.TrimEnd(Path.DirectorySeparatorChar),StringComparison.OrdinalIgnoreCase))throw new IOException("Escolha uma pasta de dados, não a raiz do volume.");
  if(OperatingSystem.IsWindows())foreach(var folder in new[]{Environment.SpecialFolder.Windows,Environment.SpecialFolder.ProgramFiles,Environment.SpecialFolder.ProgramFilesX86,Environment.SpecialFolder.CommonApplicationData}){var blocked=Environment.GetFolderPath(folder);if(blocked.Length>0&&Inside(full,blocked))throw new IOException("Pasta protegida do sistema não aceita como origem/destino.");}NoLinks(full);
 }
 public static string Relative(string relative){if(relative.Length==0||relative.Length>2048||relative.StartsWith('/')||relative.Contains('\\')||relative.Contains(':')||relative.Any(char.IsControl))throw new IOException("Caminho relativo inválido.");foreach(var part in relative.Split('/'))if(part.Length==0||part is "." or ".."||part.EndsWith('.')||part.EndsWith(' ')||Regex.IsMatch(part,@"^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\.|$)",RegexOptions.IgnoreCase)||part.IndexOfAny(['<','>','"','|','?','*'])>=0)throw new IOException("Nome não restaurável de forma segura no Windows.");return relative;}
 public static bool Excluded(string relative,IEnumerable<string> patterns){var value=relative.Replace('\\','/');return patterns.Any(pattern=>{var p=pattern.Replace('\\','/').Trim();if(p.Length==0)return false;var expression="^"+Regex.Escape(p).Replace(@"\*\*",".*").Replace(@"\*",".*").Replace(@"\?",".")+"$";return Regex.IsMatch(value,expression,RegexOptions.IgnoreCase,TimeSpan.FromMilliseconds(100))||value.StartsWith(p.TrimEnd('/')+"/",StringComparison.OrdinalIgnoreCase);});}
 public static bool LiveDatabase(string path)=>new[]{".mdf",".ndf",".ldf",".edb",".vhd",".vhdx",".avhdx"}.Contains(Path.GetExtension(path).ToLowerInvariant());
 public static IEnumerable<string> Enumerate(string root,string workRoot,IEnumerable<string> excluded,Action<string> error,CancellationToken ct){var stack=new Stack<string>();stack.Push(root);while(stack.Count>0){ct.ThrowIfCancellationRequested();var folder=stack.Pop();if(Inside(folder,workRoot))continue;IEnumerator<string>? entries=null;try{NoLinks(folder);entries=Directory.EnumerateFileSystemEntries(folder).GetEnumerator();}catch(Exception ex)when(ex is IOException or UnauthorizedAccessException){error(folder+": "+ex.Message);continue;}using(entries){while(true){ct.ThrowIfCancellationRequested();bool next;try{next=entries.MoveNext();}catch(Exception ex)when(ex is IOException or UnauthorizedAccessException){error(folder+": "+ex.Message);break;}if(!next)break;var path=entries.Current;var relative=Path.GetRelativePath(root,path).Replace('\\','/');if(Excluded(relative,excluded)||Inside(path,workRoot))continue;FileAttributes attr;try{attr=File.GetAttributes(path);NoLinks(path);}catch(Exception ex)when(ex is IOException or UnauthorizedAccessException){error(relative+": "+ex.Message);continue;}if((attr&(FileAttributes.Offline|FileAttributes.ReparsePoint))!=0||((int)attr&0x440000)!=0){error(relative+": item somente online/redirecionado não lido.");continue;}if((attr&FileAttributes.Directory)!=0){stack.Push(path);continue;}yield return path;}}}}
 public static void Atomic(string path,string text){NoLinks(path);var temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(var output=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){using var writer=new StreamWriter(output,Encoding.UTF8,65536,true);writer.Write(text);writer.Flush();output.Flush(true);}File.Move(temp,path,true);}finally{if(File.Exists(temp))File.Delete(temp);}}
 public static string SafeChild(string root,params string[] parts){var path=Path.GetFullPath(Path.Combine(new[]{root}.Concat(parts).ToArray()));if(!Inside(path,root))throw new IOException("Caminho escapou da pasta autorizada.");NoLinks(path);return path;}
}
